package com.fitnutri.backend.records;

import com.fitnutri.backend.activity.*;
import com.fitnutri.backend.common.BusinessException;
import com.fitnutri.backend.foodreference.*;
import com.fitnutri.backend.profile.*;
import com.fitnutri.backend.submission.*;
import com.fitnutri.backend.support.PostgresIntegrationSupport;
import com.fitnutri.backend.user.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import static org.junit.jupiter.api.Assertions.*;

class RecordCorrectionsIntegrationTest extends PostgresIntegrationSupport {
    @Autowired FoodRecordService foodService;@Autowired ExerciseRecordService exerciseService;@Autowired RecordReadService reads;@Autowired ExerciseEstimateService estimates;@Autowired FoodRecordRepository foods;@Autowired ExerciseRecordRepository exercises;@Autowired FoodReferenceRepository references;@Autowired ExerciseTypeRepository types;@Autowired FoodDatasetRepository foodDatasets;@Autowired ActivityDatasetRepository activityDatasets;@Autowired UserRepository users;@Autowired ProfileService profiles;@Autowired WeightService weights;@Autowired SubmissionService submissions;
    private RecordFixtureFactory fixtures;
    @BeforeEach void fixtures(){fixtures=new RecordFixtureFactory(users,profiles,foodDatasets,references,activityDatasets,types);}
    private LocalDate day(int d){return LocalDate.of(2020,1,d);}
    private FoodBatchRequest foodInput(FoodReference f){return new FoodBatchRequest(UUID.randomUUID(),day(2),"Australia/Sydney",RecordSource.IMAGE,List.of(new FoodBatchRequest.Item(UUID.randomUUID(),f.getId().toString(),new BigDecimal("100"),MealType.LUNCH)));}
    private FoodRecord food(User u,FoodReference f){var proof=foodService.confirmBatch(u.getId(),foodInput(f));return foods.findById(Long.valueOf(proof.records().getFirst().id())).orElseThrow();}
    private CreateExerciseRecordRequest exerciseInput(User u,ExerciseType t){var p=estimates.estimate(u.getId(),t.getId(),day(2),BigDecimal.TEN,"Australia/Sydney");return new CreateExerciseRecordRequest(UUID.randomUUID(),day(2),"Australia/Sydney",RecordSource.VOICE,t.getId().toString(),BigDecimal.TEN,UUID.randomUUID(),p.calculationFingerprint());}
    private ExerciseRecord exercise(User u,ExerciseType t){var proof=exerciseService.confirmExercise(u.getId(),exerciseInput(u,t));return exercises.findById(Long.valueOf(proof.records().getFirst().id())).orElseThrow();}
    private UpdateFoodRecordRequest foodUpdate(FoodRecord r,String grams,MealType meal,LocalDate date){return new UpdateFoodRecordRequest(r.getVersion(),r.getReference().getId().toString(),new BigDecimal(grams),meal,date,"Australia/Sydney");}
    private UpdateExerciseRecordRequest exerciseUpdate(ExerciseRecord r,String minutes,LocalDate date,String fingerprint){return new UpdateExerciseRecordRequest(r.getVersion(),r.getReference().getId().toString(),new BigDecimal(minutes),date,"Australia/Sydney",fingerprint);}
    @Test void foodPortionCorrectionMovesOnlyThatRecordAndPreservesOriginalSourceIdentity(){
        var u=fixtures.owner();var f=fixtures.food("659");var r=food(u,f);var updated=foodService.updateOwned(u.getId(),r.getId(),foodUpdate(r,"150",MealType.DINNER,day(3)));
        assertEquals(new BigDecimal("988.500"),updated.nutrients().energyKj());assertEquals(new BigDecimal("4.650"),updated.nutrients().proteinGrams());assertEquals(1,updated.version());assertEquals("IMAGE",updated.source());assertEquals(r.getClientEntryId(),updated.clientEntryId());assertTrue(reads.listFoods(u.getId(),day(2),day(2),null,null).isEmpty());assertEquals(updated,reads.listFoods(u.getId(),day(3),day(3),null,null).getFirst());
    }
    @Test void foodMealAndDateOnlyPreservePartialLegacySnapshotAndInactiveOriginal(){
        var u=fixtures.owner();var f=fixtures.food("659");var r=food(u,f);r.setDataQuality(DataQuality.LEGACY_UNVERIFIED);r.setEnergyKj(null);r.setProteinGramsSnapshot(BigDecimal.ZERO);r.setSource(RecordSource.PHOTO);r=foods.saveAndFlush(r);f.setActive(false);references.saveAndFlush(f);var updated=foodService.updateOwned(u.getId(),r.getId(),foodUpdate(r,"100.0000",MealType.SNACK,day(3)));
        assertNull(updated.nutrients().energyKj());assertEquals(new BigDecimal("0.000"),updated.nutrients().proteinGrams());assertEquals(DataQuality.LEGACY_UNVERIFIED,updated.dataQuality());assertFalse(updated.reference().active());assertEquals(RecordSource.PHOTO,foods.findById(r.getId()).orElseThrow().getSource());
    }
    @Test void noOpPutDoesNotRecalculateOrIncrementVersionAfterWeightAndActivationChanges(){
        var u=fixtures.owner();var f=fixtures.food("659");var t=fixtures.exercise("3.5");var food=food(u,f);var exercise=exercise(u,t);var foodBefore=reads.getFood(u.getId(),food.getId());var exerciseBefore=reads.getExercise(u.getId(),exercise.getId());weights.upsertByDate(u.getId(),new AddWeightRequest(day(1),new BigDecimal("80"),0L,"Australia/Sydney"));f.setActive(false);references.saveAndFlush(f);t.setActive(false);types.saveAndFlush(t);
        var foodAfter=foodService.updateOwned(u.getId(),food.getId(),foodUpdate(food,"100",MealType.LUNCH,day(2)));var exerciseAfter=exerciseService.updateOwned(u.getId(),exercise.getId(),exerciseUpdate(exercise,"10.00",day(2),null));assertEquals(foodBefore.updatedAt(),foodAfter.updatedAt());assertEquals(exerciseBefore.updatedAt(),exerciseAfter.updatedAt());assertEquals(0,foodAfter.version());assertEquals(0,exerciseAfter.version());assertEquals(new BigDecimal("170.847"),exerciseAfter.estimatedKj());assertEquals(new BigDecimal("70.00"),exerciseAfter.weightKgUsed());
    }
    @Test void owningInactiveOriginalCanRecalculateButDifferentInactiveReferenceCannotBeSelected(){
        var u=fixtures.owner();var f=fixtures.food("659");var t=fixtures.exercise("3.5");var food=food(u,f);var exercise=exercise(u,t);f.setActive(false);references.saveAndFlush(f);t.setActive(false);types.saveAndFlush(t);
        assertEquals(new BigDecimal("988.500"),foodService.updateOwned(u.getId(),food.getId(),foodUpdate(food,"150",MealType.LUNCH,day(2))).nutrients().energyKj());var p=estimates.estimateOriginalReference(u.getId(),t,day(2),new BigDecimal("20"),"Australia/Sydney");assertEquals(new BigDecimal("341.693"),exerciseService.updateOwned(u.getId(),exercise.getId(),exerciseUpdate(exercise,"20",day(2),p.calculationFingerprint())).estimatedKj());
        var otherFood=fixtures.food("100");otherFood.setActive(false);references.saveAndFlush(otherFood);var otherType=fixtures.exercise("4");otherType.setActive(false);types.saveAndFlush(otherType);var fNow=foods.findById(food.getId()).orElseThrow();var eNow=exercises.findById(exercise.getId()).orElseThrow();assertEquals("REFERENCE_INACTIVE",assertThrows(BusinessException.class,()->foodService.updateOwned(u.getId(),food.getId(),new UpdateFoodRecordRequest(fNow.getVersion(),otherFood.getId().toString(),new BigDecimal("150"),MealType.LUNCH,day(2),"Australia/Sydney"))).code());assertEquals("REFERENCE_INACTIVE",assertThrows(BusinessException.class,()->exerciseService.updateOwned(u.getId(),exercise.getId(),new UpdateExerciseRecordRequest(eNow.getVersion(),otherType.getId().toString(),new BigDecimal("20"),day(2),"Australia/Sydney","reviewed"))).code());
    }
    @Test void changedExerciseDateRechecksDatedWeightAndRequiresCurrentReviewedFingerprint(){
        var u=fixtures.owner();var t=fixtures.exercise("3.5");var r=exercise(u,t);weights.upsertByDate(u.getId(),new AddWeightRequest(day(3),new BigDecimal("80"),null,"Australia/Sydney"));var old=estimates.estimate(u.getId(),t.getId(),day(2),BigDecimal.TEN,"Australia/Sydney");var failed=assertThrows(CalculationChangedException.class,()->exerciseService.updateOwned(u.getId(),r.getId(),exerciseUpdate(r,"10",day(4),old.calculationFingerprint())));assertEquals(new BigDecimal("195.253"),failed.currentPreview().estimatedKj());assertEquals(0,exercises.findById(r.getId()).orElseThrow().getVersion());
        var updated=exerciseService.updateOwned(u.getId(),r.getId(),exerciseUpdate(r,"10",day(4),failed.currentPreview().calculationFingerprint()));assertEquals(1,updated.version());assertEquals(day(3),updated.weightDateUsed());assertEquals("VOICE",updated.source());assertTrue(reads.listExercises(u.getId(),day(2),day(2),null,null).isEmpty());assertEquals(updated,reads.listExercises(u.getId(),day(4),day(4),null,null).getFirst());
    }
    @Test void staleVersionAndChangedInputsWithoutFingerprintRejectWithoutOverwriting(){
        var u=fixtures.owner();var f=fixtures.food("659");var food=food(u,f);var t=fixtures.exercise("3.5");var exercise=exercise(u,t);var precision=assertThrows(BusinessException.class,()->foodService.updateOwned(u.getId(),food.getId(),foodUpdate(food,"0.0001",MealType.LUNCH,day(2))));assertEquals("quantityGrams",precision.fields().getFirst().field());assertEquals(food.getClientEntryId().toString(),precision.fields().getFirst().clientEntryId());foodService.updateOwned(u.getId(),food.getId(),foodUpdate(food,"150",MealType.SNACK,day(2)));assertEquals("VERSION_CONFLICT",assertThrows(BusinessException.class,()->foodService.updateOwned(u.getId(),food.getId(),foodUpdate(food,"200",MealType.DINNER,day(2)))).code());assertEquals("VALIDATION_ERROR",assertThrows(BusinessException.class,()->exerciseService.updateOwned(u.getId(),exercise.getId(),exerciseUpdate(exercise,"20",day(2),null))).code());assertEquals(0,exercises.findById(exercise.getId()).orElseThrow().getVersion());
    }
    @Test void realConcurrentFoodCorrectionsHaveOneSuccessAndOneVersionConflict() throws Exception {
        var u=fixtures.owner();var r=food(u,fixtures.food("659"));var first=foodUpdate(r,"150",MealType.LUNCH,day(2));var second=foodUpdate(r,"200",MealType.DINNER,day(2));var start=new CountDownLatch(1);
        try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->correctFood(start,u.getId(),r.getId(),first));var b=pool.submit(()->correctFood(start,u.getId(),r.getId(),second));start.countDown();var results=new HashSet<>(List.of(a.get(15,TimeUnit.SECONDS),b.get(15,TimeUnit.SECONDS)));assertEquals(Set.of("UPDATED","VERSION_CONFLICT"),results);assertEquals(1,foods.findById(r.getId()).orElseThrow().getVersion());}
    }
    private String correctFood(CountDownLatch start,Long owner,Long id,UpdateFoodRecordRequest request) throws Exception {start.await();try{foodService.updateOwned(owner,id,request);return "UPDATED";}catch(BusinessException e){return e.code();}}
    @Test void softDeleteIsVersionedRepeatableAndNeverDestroysOrReplaysAwayCreationProof(){
        var u=fixtures.owner();var f=fixtures.food("659");var t=fixtures.exercise("3.5");var foodInput=foodInput(f);var exerciseInput=exerciseInput(u,t);var foodProof=foodService.confirmBatch(u.getId(),foodInput);var exerciseProof=exerciseService.confirmExercise(u.getId(),exerciseInput);Long foodId=Long.valueOf(foodProof.records().getFirst().id()),exerciseId=Long.valueOf(exerciseProof.records().getFirst().id());foodService.softDeleteOwned(u.getId(),foodId,0L);exerciseService.softDeleteOwned(u.getId(),exerciseId,0L);foodService.softDeleteOwned(u.getId(),foodId,0L);exerciseService.softDeleteOwned(u.getId(),exerciseId,0L);
        assertThrows(BusinessException.class,()->reads.getFood(u.getId(),foodId));assertThrows(BusinessException.class,()->reads.getExercise(u.getId(),exerciseId));assertEquals(1,foods.findById(foodId).orElseThrow().getVersion());assertEquals(1,exercises.findById(exerciseId).orElseThrow().getVersion());assertNotNull(foods.findById(foodId).orElseThrow().getDeletedAt());assertEquals(foodProof.records(),foodService.confirmBatch(u.getId(),foodInput).records());assertEquals(exerciseProof.records(),exerciseService.confirmExercise(u.getId(),exerciseInput).records());assertTrue(reads.listFoods(u.getId(),day(2),day(2),null,null).isEmpty());assertTrue(reads.listExercises(u.getId(),day(2),day(2),null,null).isEmpty());
    }
    @Test void foreignAndMissingCorrectionsAndDeletesAreIdentical404(){
        var u=fixtures.owner();var other=fixtures.owner();var food=food(u,fixtures.food("659"));var exercise=exercise(u,fixtures.exercise("3.5"));assertEquals("NOT_FOUND",assertThrows(BusinessException.class,()->foodService.updateOwned(other.getId(),food.getId(),foodUpdate(food,"150",MealType.LUNCH,day(2)))).code());assertEquals("NOT_FOUND",assertThrows(BusinessException.class,()->exerciseService.updateOwned(other.getId(),exercise.getId(),exerciseUpdate(exercise,"10",day(2),null))).code());assertEquals("NOT_FOUND",assertThrows(BusinessException.class,()->foodService.softDeleteOwned(other.getId(),food.getId(),0L)).code());assertEquals("NOT_FOUND",assertThrows(BusinessException.class,()->exerciseService.softDeleteOwned(other.getId(),exercise.getId(),0L)).code());assertEquals("NOT_FOUND",assertThrows(BusinessException.class,()->foodService.softDeleteOwned(other.getId(),999999999L,0L)).code());assertEquals(0,foods.findById(food.getId()).orElseThrow().getVersion());
    }
    @Test void staleDeleteAndDisabledOwnerCannotMutateRecords(){
        var u=fixtures.owner();var r=food(u,fixtures.food("659"));assertEquals("VERSION_CONFLICT",assertThrows(BusinessException.class,()->foodService.softDeleteOwned(u.getId(),r.getId(),1L)).code());u.setEnabled(false);users.saveAndFlush(u);assertEquals("UNAUTHENTICATED",assertThrows(BusinessException.class,()->foodService.softDeleteOwned(u.getId(),r.getId(),0L)).code());assertNull(foods.findById(r.getId()).orElseThrow().getDeletedAt());
    }
    @Test void explicitReferenceSelectionCanUpgradeUnlinkedLegacySnapshotsWithoutErasingRawInputs(){
        var u=fixtures.owner();var f=fixtures.food("659");var t=fixtures.exercise("3.5");var food=new FoodRecord();food.setUser(u);food.setFoodName("Unlinked legacy food");food.setQuantityGramsSnapshot(new BigDecimal("100"));food.setQuantityGrams(100.0);food.setCalories(123.456);food.setMealType(MealType.LUNCH);food.setSource(RecordSource.PHOTO);food.setRecordDate(day(2));food.setRecordedAt(Instant.parse("2020-01-02T00:00:00Z"));food.setClientEntryId(UUID.randomUUID());foods.saveAndFlush(food);
        var changedFood=foodService.updateOwned(u.getId(),food.getId(),new UpdateFoodRecordRequest(0L,f.getId().toString(),new BigDecimal("100"),MealType.LUNCH,day(2),"Australia/Sydney"));assertEquals(DataQuality.CURRENT,changedFood.dataQuality());assertEquals(new BigDecimal("659.000"),changedFood.nutrients().energyKj());assertEquals("IMAGE",changedFood.source());assertEquals(123.456,foods.findById(food.getId()).orElseThrow().getCalories());
        var exercise=new ExerciseRecord();exercise.setUser(u);exercise.setExerciseType("Unlinked legacy exercise");exercise.setDurationMinutes(BigDecimal.TEN);exercise.setEstimatedCalories(111.0);exercise.setEstimatedKj(new BigDecimal("464.424"));exercise.setSource(RecordSource.PHOTO);exercise.setRecordDate(day(2));exercise.setRecordedAt(Instant.parse("2020-01-02T00:00:00Z"));exercise.setClientEntryId(UUID.randomUUID());exercises.saveAndFlush(exercise);var preview=estimates.estimate(u.getId(),t.getId(),day(2),BigDecimal.TEN,"Australia/Sydney");var changedExercise=exerciseService.updateOwned(u.getId(),exercise.getId(),new UpdateExerciseRecordRequest(0L,t.getId().toString(),BigDecimal.TEN,day(2),"Australia/Sydney",preview.calculationFingerprint()));assertEquals(DataQuality.CURRENT,changedExercise.dataQuality());assertEquals(new BigDecimal("170.847"),changedExercise.estimatedKj());assertEquals(111.0,exercises.findById(exercise.getId()).orElseThrow().getEstimatedCalories());assertEquals("IMAGE",changedExercise.source());
    }
    @Test void realConcurrentExerciseCorrectionsDoNotAutomaticallyOverwriteTheNewVersion() throws Exception {
        var u=fixtures.owner();var t=fixtures.exercise("3.5");var r=exercise(u,t);var first=estimates.estimate(u.getId(),t.getId(),day(2),new BigDecimal("20"),"Australia/Sydney");var second=estimates.estimate(u.getId(),t.getId(),day(2),new BigDecimal("30"),"Australia/Sydney");var aRequest=exerciseUpdate(r,"20",day(2),first.calculationFingerprint());var bRequest=exerciseUpdate(r,"30",day(2),second.calculationFingerprint());var start=new CountDownLatch(1);
        try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->correctExercise(start,u.getId(),r.getId(),aRequest));var b=pool.submit(()->correctExercise(start,u.getId(),r.getId(),bRequest));start.countDown();assertEquals(Set.of("UPDATED","VERSION_CONFLICT"),new HashSet<>(List.of(a.get(15,TimeUnit.SECONDS),b.get(15,TimeUnit.SECONDS))));assertEquals(1,exercises.findById(r.getId()).orElseThrow().getVersion());}
    }
    private String correctExercise(CountDownLatch start,Long owner,Long id,UpdateExerciseRecordRequest request) throws Exception {start.await();try{exerciseService.updateOwned(owner,id,request);return "UPDATED";}catch(BusinessException e){return e.code();}}
}
